class AutoSklearnPipeline(BaseComponent):
    def __init__(self, pipeline_dict: Dict) -> None:
        super().__init__()

        self.pipeline_dict = pipeline_dict

    @staticmethod
    def from_dict(pipeline_dict: Dict) -> "AutoSklearnPipeline":
        return AutoSklearnPipeline(pipeline_dict)

    @property
    def nodes(self) -> List[BaseNode]:
        return [Node.from_dict(node) for node in self.pipeline_dict["nodes"]]

    @property
    def edges(self) -> List[Tuple[int, int]]:
        return [(edge[0], edge[1]) for edge in self.pipeline_dict["edges"]]

    @property
    def input_nodes(self) -> List[int]:
        return self.pipeline_dict["input_nodes"]

    @property
    def output_nodes(self) -> List[int]:
        return self.pipeline_dict["output_nodes"]

    def to_json(self) -> str:
        return json.dumps(self.pipeline_dict)

    def save(self, path: str) -> None:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(self.to_json())
